  "inlineSchema": "// StudyCircle domain model — see docs/productspec.md §5 (Core concepts).\n// SQLite for zero-friction local dev (no enums; string fields note their\n// allowed values). Swap the datasource + adapter for Postgres in production.\n\ngenerator client {\n  provider = \"prisma-client\"\n  output   = \"../src/generated/prisma\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n}\n\n// ---------- Users & auth ----------\n\nmodel User {\n  id            String    @id @default(cuid())\n  email         String    @unique // must end in @calpoly.edu (enforced in app code)\n  emailVerified DateTime?\n  name          String?\n  major         String?\n  interests     String? // comma-separated for now; revisit with notes-privacy open question\n  avatarUrl     String?\n  createdAt     DateTime  @default(now())\n\n  enrollments          Enrollment[]\n  messages             Message[]\n  meetupsCreated       Meetup[]              @relation(\"MeetupCreator\")\n  meetupAttendances    MeetupAttendee[]\n  notes                Note[]\n  notificationSettings NotificationSetting[]\n}\n\nmodel VerificationToken {\n  token     String   @id\n  email     String\n  expiresAt DateTime\n}\n\n// ---------- Catalog (prefetched from Cal Poly — open question #1) ----------\n\nmodel Course {\n  id       String    @id @default(cuid())\n  code     String // e.g. \"CSC 202\"\n  title    String\n  term     String // e.g. \"Fall 2026\"\n  spaces   Space[]\n  sections Section[]\n\n  @@unique([code, term])\n}\n\nmodel Professor {\n  id        String     @id @default(cuid())\n  name      String\n  sections  Section[]\n  subspaces Subspace[]\n}\n\nmodel Section {\n  id          String  @id @default(cuid())\n  courseId    String\n  professorId String\n  sectionCode String // e.g. \"03\"\n  days        String // e.g. \"MWF\"\n  startTime   String? // \"HH:MM\"\n  endTime     String?\n  location    String?\n\n  course      Course       @relation(fields: [courseId], references: [id])\n  professor   Professor    @relation(fields: [professorId], references: [id])\n  enrollments Enrollment[]\n\n  @@unique([courseId, sectionCode])\n}\n\nmodel Enrollment {\n  userId    String\n  sectionId String\n  user      User    @relation(fields: [userId], references: [id])\n  section   Section @relation(fields: [sectionId], references: [id])\n\n  @@id([userId, sectionId])\n}\n\n// ---------- Spaces / Subspaces / Channels ----------\n\n// One Space per course per term; predefined from the catalog, never user-created.\nmodel Space {\n  id        String     @id @default(cuid())\n  courseId  String\n  course    Course     @relation(fields: [courseId], references: [id])\n  subspaces Subspace[]\n\n  @@unique([courseId])\n}\n\n// One Subspace per professor within a Space (not per section — spec §5).\nmodel Subspace {\n  id          String @id @default(cuid())\n  spaceId     String\n  professorId String\n\n  space          Space           @relation(fields: [spaceId], references: [id])\n  professor      Professor       @relation(fields: [professorId], references: [id])\n  channels       Channel[]\n  meetups        Meetup[]\n  lectureFolders LectureFolder[]\n  courseSchedule CourseSchedule?\n\n  @@unique([spaceId, professorId])\n}\n\n// Predefined channels only (spec §9: no user-created channels).\nmodel Channel {\n  id         String    @id @default(cuid())\n  subspaceId String\n  name       String // e.g. \"general\", \"homework\"\n  subspace   Subspace  @relation(fields: [subspaceId], references: [id])\n  messages   Message[]\n\n  @@unique([subspaceId, name])\n}\n\nmodel Message {\n  id           String   @id @default(cuid())\n  channelId    String\n  authorId     String? // null for @ClassAI replies\n  body         String\n  isAiResponse Boolean  @default(false)\n  meetupId     String? // set when this message pins a meetup's location/time widget\n  createdAt    DateTime @default(now())\n\n  channel Channel @relation(fields: [channelId], references: [id])\n  author  User?   @relation(fields: [authorId], references: [id])\n  meetup  Meetup? @relation(fields: [meetupId], references: [id])\n}\n\n// ---------- Meetups ----------\n\n// A meetup is a location + time posting, NOT its own group chat (spec §9).\nmodel Meetup {\n  id           String   @id @default(cuid())\n  subspaceId   String\n  creatorId    String\n  title        String\n  blurb        String?\n  locationName String\n  lat          Float?\n  lng          Float?\n  startsAt     DateTime\n  timeZone     String // IANA zone captured when the meetup is created, e.g. \"America/Los_Angeles\"\n  createdAt    DateTime @default(now())\n\n  subspace  Subspace         @relation(fields: [subspaceId], references: [id])\n  creator   User             @relation(\"MeetupCreator\", fields: [creatorId], references: [id])\n  attendees MeetupAttendee[]\n  messages  Message[]\n\n  @@index([subspaceId, startsAt])\n  @@index([creatorId, createdAt])\n}\n\nmodel MeetupAttendee {\n  meetupId String\n  userId   String\n  joinedAt DateTime @default(now())\n\n  meetup Meetup @relation(fields: [meetupId], references: [id])\n  user   User   @relation(fields: [userId], references: [id])\n\n  @@id([meetupId, userId])\n}\n\n// ---------- Notes & AI ----------\n\n// One folder per class session, auto-generated from the section schedule.\nmodel LectureFolder {\n  id         String   @id @default(cuid())\n  subspaceId String\n  date       DateTime\n  title      String? // e.g. \"Lecture 7 — Hash tables\"\n\n  subspace Subspace        @relation(fields: [subspaceId], references: [id])\n  notes    Note[]\n  summary  LectureSummary?\n\n  @@unique([subspaceId, date])\n}\n\nmodel Note {\n  id              String   @id @default(cuid())\n  lectureFolderId String\n  uploaderId      String\n  fileName        String\n  fileUrl         String\n  mimeType        String\n  createdAt       DateTime @default(now())\n\n  lectureFolder LectureFolder @relation(fields: [lectureFolderId], references: [id])\n  uploader      User          @relation(fields: [uploaderId], references: [id])\n}\n\nmodel LectureSummary {\n  id              String   @id @default(cuid())\n  lectureFolderId String   @unique\n  content         String\n  generatedAt     DateTime @default(now())\n\n  lectureFolder LectureFolder @relation(fields: [lectureFolderId], references: [id])\n}\n\n// One schedule per professor per term, shared across their sections (spec §6.6).\nmodel CourseSchedule {\n  id         String   @id @default(cuid())\n  subspaceId String   @unique\n  rawFileUrl String? // uploaded syllabus/schedule file\n  uploadedAt DateTime @default(now())\n\n  subspace Subspace       @relation(fields: [subspaceId], references: [id])\n  items    ScheduleItem[]\n}\n\n// Parsed from the syllabus by AI; dates are tentative and editable.\nmodel ScheduleItem {\n  id           String   @id @default(cuid())\n  scheduleId   String\n  type         String // \"EXAM\" | \"QUIZ\" | \"TOPIC\" | \"OTHER\"\n  title        String\n  date         DateTime\n  isCumulative Boolean? // exams only\n  topics       String?\n\n  schedule CourseSchedule @relation(fields: [scheduleId], references: [id])\n}\n\n// ---------- Notifications (email-based, spec §6.7) ----------\n\nmodel NotificationSetting {\n  userId       String\n  event        String // \"MEETUP_JOIN\" | \"NEW_MESSAGE\" | \"MENTION\" | \"EXAM_REMINDER\"\n  emailEnabled Boolean @default(true)\n\n  user User @relation(fields: [userId], references: [id])\n\n  @@id([userId, event])\n}\n",
